use vstd::prelude::*;

verus! {
    /// Returns the minimum element of a non‐empty array of 32‐bit signed integers.
    ///
    /// # Preconditions
    /// - `a.len() > 0`
    ///
    /// # Postconditions
    /// - The result is less than or equal to every element of `a`.
    /// - The result is equal to at least one element of `a`.
    pub fn min_array(a: &Vec<i32>) -> (result: i32)
        requires
            a.len() > 0,
        ensures
            // result is at most every element in the array
            forall |j: usize| j < a.len() ==> result <= a[j],
        ensures
            // result appears somewhere in the array
            exists |j: usize| j < a.len() && a[j] == result,
    {
        // Initialize the current minimum to the first element
        let mut min_val: i32 = a[0];
        let mut i: usize = 1;

        // Traverse the remainder of the array
        while i < a.len()
            invariant
                // i never exceeds the array length
                i <= a.len(),
            invariant
                // min_val is at most all elements we've seen so far
                forall |j: usize| j < i ==> min_val <= a[j],
            invariant
                // min_val actually equals one of the elements we've seen
                exists |j: usize| j < i && a[j] == min_val,
            decreases
                a.len() - i,
        {
            if a[i] < min_val {
                min_val = a[i];
            }
            i += 1;
        }

        // Return the found minimum
        result = min_val;
    }
}